for cid, v in YM.items():
    CASES[cid] = dict(conf=v["conf"], trig=v["trig"], prediction_text=v["prediction_text"],
        basis="tradition=liuyao\nsystems_used=liuyao\n" + v["basis_extra"])

def main():
    batches = json.load(open(os.path.join(BASE, "batches.json"), encoding="utf-8"))
    ids = batches["B21"] + batches["B22"]
    assert len(ids) == 40, len(ids)
    total = 0
    for cid in ids:
        c = CASES[cid]
        obj = {"case_id": cid, "prediction_text": c["prediction_text"], "basis": c["basis"],
               "confidence": c["conf"], "trigger": c["trig"]}
        p = os.path.join(OUT, cid + ".json")
        with open(p, "w", encoding="utf-8") as f:
            json.dump(obj, f, ensure_ascii=False, indent=1)
        total += os.path.getsize(p)
    # verify per-id exact open
    tc = {"changed_main": 0, "reserve_used": 0, "disputed": 0}
    trad = {}
    for cid in ids:
        o = json.load(open(os.path.join(OUT, cid + ".json"), encoding="utf-8"))
        assert set(o.keys()) == {"case_id", "prediction_text", "basis", "confidence", "trigger"}, cid
        assert o["case_id"] == cid and 0 <= o["confidence"] <= 1
        assert set(o["trigger"].keys()) == {"changed_main", "reserve_used", "disputed", "reason"}
        for k in tc:
            tc[k] += 1 if o["trigger"][k] else 0
        t = o["basis"].splitlines()[0].replace("tradition=", "")
        trad[t] = trad.get(t, 0) + 1
    print("written", len(ids), "bytes", total)
    print("trigger_counts", tc)
    print("tradition", trad)

if __name__ == "__main__":
    main()
